contentRule.content:
#txt@html##阅读.*最新章节.*|.*查找最新章节|www.*
<js>
var matches = result.match(/<dd data-id="(\d+)"[\s\S]*?<\/dd>/g) || [];
if (matches.length > 0){
    var elementsWithId = matches.map(function(element) {
        var match = element.match(/<dd data-id="(\d+)"/);
        return {
            element: element,
            id: parseInt(match[1])
        };
    });
    elementsWithId.sort(function(a, b) {
        return a.id - b.id;
    });
    var sortedElements = elementsWithId.map(function(item) {
        return item.element;
    });
    sortedElements.join('\n');
} else {
    result
}
</js>

source.exploreUrl:
@js:
var result = [];
java.toast("🔥正在刷新列表,请稍等！");
var push = (title, url, size) => result.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});
var baseUrl = "https://www.minixiaoshuow.com/sort/";
var tag = java.ajax(baseUrl);
if (tag) {
    var a = org.jsoup.Jsoup.parse(tag).select(".leftbar ul li a");
    push("🔥分类小说🔥", null, 1);
    for (var i = 2; i < a.length ; i++) {
        var title = a[i].text();
        var url = a[i].attr("href");
        var size = 0.25;
        title = String(title).replace(/\s/g, "");
        url = String(url).replace(/1\./,'{{page}}.');      
        push(title, url, size);
    }
} else {
  java.toast("🤔列表刷新失败！！！");     
} 
JSON.stringify(result);

